<script setup lang="ts">
import { ref } from 'vue'
import { useStudioStore } from '@/stores/studio'
import AppIcon from '@/components/AppIcon.vue'
const studio = useStudioStore(); const providerId = ref(studio.model.providerId); const modelId = ref(studio.model.modelId); const saved = ref(false)
async function save() { saved.value = false; try { await studio.saveModel({ providerId: providerId.value, modelId: modelId.value }); saved.value = true } catch (err) { studio.error = err instanceof Error ? err.message : String(err) } }
</script>
<template><div class="page settings-page"><div class="page-heading"><div><h1>Mira 连接</h1><p>模型、密钥和作品数据由 Mira App 管理。Novel Studio 只提交创作请求。</p></div><span class="connection-large"><i :class="{ online: studio.connection === 'ready' }" />{{ studio.preview ? '浏览示例' : studio.connection === 'ready' ? '已连接' : '未连接' }}</span></div><p v-if="studio.preview" class="connection-notice"><AppIcon name="info" :size="16" />当前 Mira 尚未开放小说存储与文本生成接口。这里展示接入方案，创作能力暂不可用。</p><section class="settings-section"><div class="settings-section-head"><span class="settings-icon"><AppIcon name="key-round" :size="19" /></span><div><h2>创作模型</h2><p>填写 Mira 中已配置的供应商和模型标识；这里不保存密钥。</p></div></div><div class="settings-fields"><label for="provider">供应商 ID<input id="provider" v-model="providerId" :disabled="!studio.writable" placeholder="例如 provider-id" /></label><label for="model">模型 ID<input id="model" v-model="modelId" :disabled="!studio.writable" placeholder="例如 model-id" /></label></div><button class="button primary" :disabled="!studio.writable" @click="save">{{ saved ? '已保存' : '保存模型选择' }}<AppIcon :name="saved ? 'check' : 'arrow-right'" :size="15" /></button><p v-if="studio.preview" class="settings-warning"><AppIcon name="eye" :size="15" />浏览模式不保存配置；需等待 Mira 完成创作接口接入后使用。</p></section><section class="settings-section boundary-section"><div class="settings-section-head"><span class="settings-icon quiet"><AppIcon name="shield-check" :size="19" /></span><div><h2>能力边界</h2><p>这是应用和 Mira 之间的明确分工。</p></div></div><div class="boundary-list"><div><strong>Novel Studio</strong><span>故事蓝图、章节规划、上下文组装、正文编辑、审阅和记忆提案</span></div><div><strong>Mira App</strong><span>模型凭据、模型调用、作品数据库、应用授权和连接生命周期</span></div></div></section><RouterLink to="/" class="text-button"><AppIcon name="arrow-left" :size="15" />回到我的作品</RouterLink></div></template>
